#include "navigation.h"
#include <math.h>
static double rad(double x){return x*M_PI/180.0;} static double deg(double x){return x*180.0/M_PI;} static double wrap(double x){while(x<0)x+=360;while(x>=360)x-=360;return x;}
TargetVector makeTargetVector(const LocalFix&l,const TrackerFix&t,double heading){TargetVector v;if(!l.valid||!t.valid)return v;double p1=rad(l.lat),p2=rad(t.lat),dlon=rad(t.lon-l.lon),dlat=rad(t.lat-l.lat);double a=sin(dlat/2)*sin(dlat/2)+cos(p1)*cos(p2)*sin(dlon/2)*sin(dlon/2);v.distance_m=6371000.0*2*atan2(sqrt(a),sqrt(1-a));double y=sin(dlon)*cos(p2),x=cos(p1)*sin(p2)-sin(p1)*cos(p2)*cos(dlon);v.bearing_deg=wrap(deg(atan2(y,x)));v.north_m=v.distance_m*cos(rad(v.bearing_deg));v.east_m=v.distance_m*sin(rad(v.bearing_deg));v.relative_deg=wrap(v.bearing_deg-heading);v.valid=true;return v;}
void HeadingEstimator::reset(){heading_deg=0;initialized=false;course_valid=false;lastMoveMs=0;}
void HeadingEstimator::update(float gz,float dt,const LocalFix&l){ if(!initialized){heading_deg=l.valid&&l.speed_mps>1.0?l.course:0;initialized=true;lastLat=l.lat;lastLon=l.lon;} heading_deg=wrap(heading_deg+gz*dt); if(l.valid && l.speed_mps>1.5 && l.course>=0 && l.course<360){ double e=l.course-heading_deg; while(e>180)e-=360;while(e<-180)e+=360; float alpha=constrain((float)(dt*0.9),0.02f,0.18f); heading_deg=wrap(heading_deg+e*alpha); course_valid=true; lastLat=l.lat;lastLon=l.lon;lastMoveMs=millis(); } }
